import{_ as l,W as i,s as o,u as d,ah as u,I as t,w as n,Z as e,A as p}from"./chunks/framework.DRqsSc0o.js";import"./chunks/theme.DlTh90wK.js";const L=JSON.parse('{"title":"使用 Linux 终端查看你的电脑上有哪些文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 终端查看你的电脑上有哪些文件 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 终端查看你的电脑上有哪些文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 终端查看你的电脑上有哪些文件 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210801 Use the Linux terminal to see what files are on your computer","title":"使用 Linux 终端查看你的电脑上有哪些文件","tag":"202108"},"relativePath":"202108/20210801 Use the Linux terminal to see what files are on your computer.md","filePath":"[post].md"}'),r={name:"202108/20210801 Use the Linux terminal to see what files are on your computer.md"};function c(m,s,h,x,f,g){const a=i("Link");return d(),o("div",null,[s[15]||(s[15]=u(`<h1 id="使用-linux-终端查看你的电脑上有哪些文件" tabindex="-1">使用 Linux 终端查看你的电脑上有哪些文件 <a class="header-anchor" href="#使用-linux-终端查看你的电脑上有哪些文件" aria-label="Permalink to 使用 Linux 终端查看你的电脑上有哪些文件">​</a></h1><blockquote><p>通过这个 Linux 教程学习如何使用 ls 命令在终端中列出文件。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/11/142450etebpqtp7bl4kupt.jpg" alt=""></p><p>要在有图形界面的计算机上列出文件，你通常可以打开一个文件管理器（Linux 上的 “文件”，MacOS 上的 “访达”，Windows 上的 “文件资源管理器”）来查看文件。</p><p>要在终端中列出文件，你可以使用 <code>ls</code> 命令来列出当前目录中的所有文件。而 <code>pwd</code> 命令可以告诉你当前所在的目录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/tux</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>example.txt</span></span>
<span class="line"><span>Documents</span></span>
<span class="line"><span>Downloads</span></span>
<span class="line"><span>Music</span></span>
<span class="line"><span>Pictures</span></span>
<span class="line"><span>Templates</span></span>
<span class="line"><span>Videos</span></span></code></pre></div><p>你可以通过 <code>--all</code>（简写为 <code>-a</code>） 选项看到隐藏文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/tux</span></span>
<span class="line"><span>$ ls --all</span></span>
<span class="line"><span>.               Downloads</span></span>
<span class="line"><span>..              .local</span></span>
<span class="line"><span>.bashrc         Music</span></span>
<span class="line"><span>.config         Pictures</span></span>
<span class="line"><span>example.txt     Templates</span></span>
<span class="line"><span>Documents       Videos</span></span></code></pre></div><p>如你所见，列出的前两项是点。单个点（<code>.</code>）实际上是一个元位置，代表 <em>你当前所在的文件夹</em> 。两个点（<code>..</code>）表示你可以从当前位置返回的上级目录。也就是说，当前目录在另一个文件夹中。当你在计算机目录间移动时，你就可以利用这些元位置为自己创建快捷方式，或者增加你的路径的独特性。</p><h3 id="文件和文件夹以及如何区分它们" tabindex="-1">文件和文件夹以及如何区分它们 <a class="header-anchor" href="#文件和文件夹以及如何区分它们" aria-label="Permalink to 文件和文件夹以及如何区分它们">​</a></h3><p>你可能会注意到，文件和文件夹是很难区分的。一些 Linux 发行版有一些漂亮的颜色设置，比如所有的文件夹都是蓝色的，文件是白色的，二进制文件是粉色或绿色的，等等。如果你没有看到这些颜色，你可以试试 <code>ls --color</code>。如果你有色盲症或者使用的不是彩色显示器，你可以使用 <code>--classify</code> 选项替代：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/tux/Downloads</span></span>
<span class="line"><span>$ ls --classify</span></span>
<span class="line"><span>android-info.txt</span></span>
<span class="line"><span>cheat/</span></span>
<span class="line"><span>test-script.sh*</span></span></code></pre></div><p>你会发现，文件夹末尾加了一个斜杠（<code>/</code>），以表示它们是文件系统中的某一级目录。而二进制文件，如压缩文件和可执行程序，用星号（<code>*</code>）标记。</p><hr>`,14)),t("p",null,[s[1]||(s[1]=n("via: ")),e(a,{href:"https://opensource.com/article/21/8/linux-list-files"},{default:p(()=>s[0]||(s[0]=[n("https://opensource.com/article/21/8/linux-list-files")])),_:1})]),t("p",null,[s[6]||(s[6]=n("作者：")),e(a,{href:"https://opensource.com/users/seth"},{default:p(()=>s[2]||(s[2]=[n("Seth Kenlon")])),_:1}),s[7]||(s[7]=n(" 选题：")),e(a,{href:"https://github.com/lujun9972"},{default:p(()=>s[3]||(s[3]=[n("lujun9972")])),_:1}),s[8]||(s[8]=n(" 译者：")),e(a,{href:"https://github.com/piaoshi"},{default:p(()=>s[4]||(s[4]=[n("piaoshi")])),_:1}),s[9]||(s[9]=n(" 校对：")),e(a,{href:"https://github.com/wxy"},{default:p(()=>s[5]||(s[5]=[n("wxy")])),_:1})]),t("p",null,[s[12]||(s[12]=n("本文由 ")),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>s[10]||(s[10]=[n("LCTT")])),_:1}),s[13]||(s[13]=n(" 原创编译，")),e(a,{href:"https://linux.cn/"},{default:p(()=>s[11]||(s[11]=[n("Linux中国")])),_:1}),s[14]||(s[14]=n(" 荣誉推出"))])])}const C=l(r,[["render",c]]);export{L as __pageData,C as default};
